refentry.refsect1:
&reftitle.parameters;


  class_name

   El nombre de la clase a cargar.

  &reftitle.examples;

   Ejemplo de Yaf_Loader::autoload


<?php
/*
 * autoload() es invocado normalmente de forma implícita por el motor
 * cada vez que se hace referencia a una clase no definida, pero también
 * puede llamarse explícitamente para forzar la carga del fichero de una clase.
 */
$loader = Yaf_Loader::getInstance("/var/www/shop/application/library");

/* busca /var/www/shop/application/library/Catalog/PriceService.php */
$loader->autoload("Catalog_PriceService");

/* las clases MVC se buscan dentro del directorio de la aplicación */
$loader->autoload("ProductController");
?>
